#!/usr/bin/env python3
import json
import math
import os
from dataclasses import dataclass
from typing import List, Dict, Optional

import numpy as np
import torch
import torchaudio
from silero_vad import load_silero_vad, get_speech_timestamps
from speechbrain.inference.speaker import SpeakerRecognition
from sklearn.cluster import AgglomerativeClustering
from sklearn.metrics import silhouette_score
import whisper

AUDIO_PATH = "/root/audio.wav"
RTTM_PATH = "/root/diarization.rttm"
ASS_PATH = "/root/subtitles.ass"
REPORT_PATH = "/root/report.json"

SR = 16000

@dataclass
class Segment:
    start: float
    end: float
    speaker: Optional[int] = None


def load_audio_mono(path: str, target_sr: int = SR) -> torch.Tensor:
    wav, sr = torchaudio.load(path)
    if wav.shape[0] > 1:
        wav = torch.mean(wav, dim=0, keepdim=True)
    if sr != target_sr:
        wav = torchaudio.functional.resample(wav, sr, target_sr)
    return wav.squeeze(0)


def merge_segments(segments: List[Dict[str, int]], sr: int, max_gap_s: float = 0.3) -> List[Dict[str, int]]:
    if not segments:
        return []
    merged = [dict(segments[0])]
    for seg in segments[1:]:
        gap = (seg["start"] - merged[-1]["end"]) / sr
        if gap <= max_gap_s:
            merged[-1]["end"] = seg["end"]
        else:
            merged.append(dict(seg))
    return merged


def ensure_min_length(start: int, end: int, min_len_samples: int, max_len_samples: int) -> (int, int):
    length = end - start
    if length >= min_len_samples:
        return start, end
    pad = min_len_samples - length
    left = pad // 2
    right = pad - left
    new_start = max(0, start - left)
    new_end = min(max_len_samples, end + right)
    # If clipped, adjust to maintain min length when possible
    if new_end - new_start < min_len_samples:
        if new_start == 0:
            new_end = min(max_len_samples, new_start + min_len_samples)
        elif new_end == max_len_samples:
            new_start = max(0, new_end - min_len_samples)
    return new_start, new_end


def estimate_num_speakers(embeddings: np.ndarray, max_k: int = 6) -> (int, np.ndarray):
    n = embeddings.shape[0]
    if n == 1:
        return 1, np.array([0])
    max_k = min(max_k, n)
    best_k = 2
    best_score = -1.0
    best_labels = None
    for k in range(2, max_k + 1):
        try:
            clustering = AgglomerativeClustering(n_clusters=k, metric="cosine", linkage="average")
            labels = clustering.fit_predict(embeddings)
            if len(set(labels)) == 1:
                continue
            score = silhouette_score(embeddings, labels, metric="cosine")
            if score > best_score:
                best_score = score
                best_k = k
                best_labels = labels
        except Exception:
            continue
    if best_labels is None:
        clustering = AgglomerativeClustering(n_clusters=2, metric="cosine", linkage="average")
        labels = clustering.fit_predict(embeddings)
        return 2, labels
    # If silhouette is very low, collapse to 1 speaker
    if best_score < 0.1:
        return 1, np.zeros(n, dtype=int)
    return best_k, best_labels


def reorder_labels_by_first_time(segments: List[Segment]) -> None:
    first_time = {}
    for seg in segments:
        if seg.speaker not in first_time:
            first_time[seg.speaker] = seg.start
    order = sorted(first_time.items(), key=lambda x: x[1])
    mapping = {old: idx for idx, (old, _) in enumerate(order)}
    for seg in segments:
        seg.speaker = mapping.get(seg.speaker, seg.speaker)


def assign_speaker_to_transcript(seg_start: float, seg_end: float, diar_segs: List[Segment]) -> int:
    overlaps = {}
    for d in diar_segs:
        overlap = max(0.0, min(seg_end, d.end) - max(seg_start, d.start))
        if overlap > 0:
            overlaps[d.speaker] = overlaps.get(d.speaker, 0.0) + overlap
    if overlaps:
        return max(overlaps.items(), key=lambda x: x[1])[0]
    # Fallback: nearest diarization segment
    mid = (seg_start + seg_end) / 2.0
    nearest = min(diar_segs, key=lambda d: abs(((d.start + d.end) / 2.0) - mid))
    return nearest.speaker


def format_ass_time(seconds: float) -> str:
    if seconds < 0:
        seconds = 0
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    s = seconds % 60
    cs = int(round((s - int(s)) * 100))
    s_int = int(s)
    if cs == 100:
        s_int += 1
        cs = 0
        if s_int == 60:
            s_int = 0
            m += 1
            if m == 60:
                m = 0
                h += 1
    return f"{h}:{m:02d}:{s_int:02d}.{cs:02d}"


def main():
    if not os.path.exists(AUDIO_PATH):
        raise FileNotFoundError(f"Missing audio at {AUDIO_PATH}")

    audio = load_audio_mono(AUDIO_PATH, SR)
    audio_len = audio.shape[0]
    audio_duration = audio_len / SR

    # VAD
    vad_model = load_silero_vad()
    speech_ts = get_speech_timestamps(audio, vad_model, sampling_rate=SR, min_speech_duration_ms=250,
                                      min_silence_duration_ms=150, speech_pad_ms=50)
    speech_ts = merge_segments(speech_ts, SR, max_gap_s=0.3)

    segments = [Segment(start=ts["start"] / SR, end=ts["end"] / SR) for ts in speech_ts]
    total_speech = sum(seg.end - seg.start for seg in segments)

    # Speaker embeddings
    if segments:
        spk_model = SpeakerRecognition.from_hparams(
            source="speechbrain/spkrec-ecapa-voxceleb",
            savedir="/root/.cache/speechbrain/spkrec-ecapa-voxceleb",
        )
        min_len_samples = int(0.5 * SR)
        embs = []
        for seg in segments:
            s = int(seg.start * SR)
            e = int(seg.end * SR)
            s2, e2 = ensure_min_length(s, e, min_len_samples, audio_len)
            wav = audio[s2:e2].unsqueeze(0)
            with torch.inference_mode():
                emb = spk_model.encode_batch(wav).squeeze(0).cpu().numpy()
            embs.append(emb)
        embeddings = np.vstack(embs) if embs else np.zeros((0, 192))
        if embeddings.shape[0] == 0:
            for seg in segments:
                seg.speaker = 0
            num_speakers = 1
        else:
            num_speakers, labels = estimate_num_speakers(embeddings, max_k=6)
            if num_speakers == 1:
                labels = np.zeros(len(segments), dtype=int)
            for seg, lbl in zip(segments, labels):
                seg.speaker = int(lbl)
        reorder_labels_by_first_time(segments)
    else:
        num_speakers = 0

    # RTTM
    with open(RTTM_PATH, "w", encoding="utf-8") as f:
        for seg in segments:
            dur = seg.end - seg.start
            f.write(
                f"SPEAKER input 1 {seg.start:.6f} {dur:.6f} <NA> <NA> spk{seg.speaker:02d} <NA> <NA>\n"
            )

    # Transcription
    if segments:
        asr_model = whisper.load_model("base")
        asr = asr_model.transcribe(AUDIO_PATH, fp16=False)
        asr_segments = asr.get("segments", [])
    else:
        asr_segments = []

    # ASS subtitles
    with open(ASS_PATH, "w", encoding="utf-8") as f:
        f.write("[Events]\n")
        f.write("Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n")
        for seg in asr_segments:
            start = float(seg.get("start", 0.0))
            end = float(seg.get("end", 0.0))
            text = (seg.get("text", "") or "").strip()
            if not text:
                continue
            spk = 0
            if segments:
                spk = assign_speaker_to_transcript(start, end, segments)
            text = text.replace("\\", "\\\\").replace("{", "\\{").replace("}", "\\}")
            text = text.replace(",", "\\,")
            line = (
                f"Dialogue: 0,{format_ass_time(start)},{format_ass_time(end)},"
                f"Default,,0,0,0,,SPEAKER_{spk:02d}: {text}\n"
            )
            f.write(line)

    report = {
        "num_speakers_pred": int(num_speakers),
        "total_speech_time_sec": round(float(total_speech), 3),
        "audio_duration_sec": round(float(audio_duration), 3),
        "steps_completed": [
            "audio_extraction",
            "diarization",
            "subtitle_generation",
        ],
        "commands_used": ["ffmpeg", "python3"],
        "libraries_used": [
            "silero-vad",
            "speechbrain",
            "scikit-learn",
            "openai-whisper",
            "numpy",
            "torch",
            "torchaudio",
        ],
        "tools_used": {
            "audio_extraction": "ffmpeg",
            "diarization": "silero-vad + speechbrain (ECAPA) + sklearn clustering",
            "subtitle_generation": "openai-whisper",
        },
        "notes": "Speaker count estimated via silhouette score over ECAPA embeddings; labels ordered by first occurrence.",
    }

    with open(REPORT_PATH, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)


if __name__ == "__main__":
    main()
